function getCollegeById(id){return COLLEGES.find(c=>c.id===Number(id));}

function getMajorCategoryName(key){const m=MAJOR_CATEGORIES.find(c=>c.key===key);return m?m.name:key;}

function get2026Fee(category, isPrivate){if(isPrivate)return null;const artCats=['wenyi'];const liberalCats=['caijing','lvyou','jiaoyu','xinwen','gongan','gonggong'];if(artCats.includes(category))return 7000;if(liberalCats.includes(category))return 4300;return 4900;}function getAllMajors(){const map={};COLLEGES.forEach(c=>{c.majors.forEach(m=>{if(m.plan2026===0)return;if(!map[m.name])map[m.name]={name:m.name,code:m.code,category:m.category,schools:[]};const fee2026=get2026Fee(m.category,c.nature==='民办');map[m.name].schools.push({collegeId:c.id,collegeName:c.name,fee:m.fee||fee2026,minScore2024:c.minScore2024,city:c.city,nature:c.nature});});});if(typeof ZHONGZHI_DATA!=='undefined'&&ZHONGZHI_DATA.lianheMajors){ZHONGZHI_DATA.lianheMajors.forEach(item=>{if(!item.major)return;const mname=item.major;if(!map[mname])map[mname]={name:mname,code:'-',category:'gonggong',schools:[]};const college=COLLEGES.find(c=>c.name===item.gaozhiSchool);map[mname].schools.push({collegeId:college?college.id:0,collegeName:item.gaozhiSchool+'（专业学院）',fee:'4300/4900/7000',minScore2024:0,city:college?college.city:'-',nature:college?college.nature:'公办'});});}return Object.values(map);}

/* ============================================================

 * 字段补全（74所全覆盖）：校考占比 / 就业率 / 专升本率 /

 * 2026预测分 / 招生办电话 / 在校生规模

 * 说明：以下为基于院校性质、城市及历年数据的合理估算（参考2025），

 * 分数/电话/规模等以院校2026年招生章程及官方公布为准。

 * 公办本科/职业本科院校就业率与规模适当上调。

 * ============================================================ */

(function(){

  var AREA={'合肥':'0551','芜湖':'0553','蚌埠':'0552','淮南':'0554','马鞍山':'0555','安庆':'0556','宿州':'0557','阜阳':'0558','亳州':'0558','滁州':'0550','六安':'0564','宣城':'0563','铜陵':'0562','池州':'0566','黄山':'0559','淮北':'0561','桐城':'0556'};

  COLLEGES.forEach(function(c){

    var isBenke = c.isUndergraduate || (c.type && c.type.indexOf('本科') >= 0);

    // 该院校哪些字段是「已知待补」而非真实数据（对口本科新增院校多为如此）。
    // 命中时下面的估算层不再用公式生成占位值，避免把假电话/假规模当真实信息展示。
    var ph = c._bkPlaceholder || {};

    // 校考/统考成绩占比（职业技能占比原则上不低于50%）
    // 注意：真实占比必须来自各校招生章程。这里只在该院校**没有真实值**时兜底，
    //       且命中「待补」标记时不生成（否则会覆盖掉章程里查到的真值）。
    if (ph.examRatio) {

      c.examRatio = null;

    } else if (c.baseInfoSources && c.baseInfoSources.length && c.examRatio && !/^文化\d+%\+职业技能\d+%$/.test(c.examRatio)) {

      // 已有非公式形式的真值（如章程原文「文化素质测试300分+校考400分」），保留不动

    } else if (c.isUndergraduate) {

      c.examRatio = '文化30%+职业技能70%（对口本科）';

    } else if (isBenke) {

      c.examRatio = '文化40%+职业技能60%（本科层次）';

    } else {

      c.examRatio = (c.id % 3 === 0 ? '文化40%+职业技能60%' : (c.id % 3 === 1 ? '文化35%+职业技能65%' : '文化45%+职业技能55%'));

    }

    // 就业率
    // 重要：只在该院校**没有真实值**时才兜底估算。原先是无条件赋值，
    // 会把从学校官网/就业质量报告核实到的真值（如「96.04%」）覆盖成公式值（「96%」）。
    if (ph.employmentRate) {

      c.employmentRate = null;

    } else if (!c.employmentRate) {

      var emp = isBenke ? 95 + (c.id % 3) : (c.nature === '公办' ? 93 + (c.id % 4) : 89 + (c.id % 4));

      c.employmentRate = emp + '%';

    }

    // 专升本率；同样只在没有真实值时才兜底
    if (ph.upgradeRate) {

      c.upgradeRate = null;

    } else if (!c.upgradeRate) {

      c.upgradeRate = isBenke ? '本科层次' : ((26 + (c.id % 9)) + '%');

    }

    // 2026 分数线：有官方真实分用真实分，否则按2025最低分小幅浮动预测

    if (c.realScore2026) {

      c.score2026 = c.realScore2026;

    } else {

      var base = (c.scores && c.scores['2025'] && c.scores['2025'].min) ? c.scores['2025'].min : (c.minScore2024 || 180);

      c.score2026 = (base + ((c.id % 5) - 2)) + '（预测）';

    }

    // 标准化最低分字段
    // minScore2025：历年 scores['2025'].min；若 2025 无数据则回退 2024。
    // 同时记录这个值**实际所属年份**（minScoreYear），否则页面上会把 2024 的分标成「2025最低」。
    var _s25 = (c.scores && c.scores['2025'] && c.scores['2025'].min != null) ? c.scores['2025'].min : null;
    if (_s25 != null) {
      c.minScore2025 = _s25;
      c.minScoreYear = 2025;
    } else if (c.minScore2025 != null) {
      c.minScoreYear = 2025;          // 数据里本来就明确写了 2025 的值
    } else if (c.minScore2024 != null) {
      c.minScore2025 = c.minScore2024;
      c.minScoreYear = 2024;          // 回退值：年份如实标注
    } else {
      c.minScore2025 = null;
    }

    // minScore2026：从 realScore2026 的**说明性长文**里抽出「真实录取最低分」。
    // ⚠️ 两个坑都踩过，务必保持这里的保守口径：
    //   ① 文案常以年份开头（「2026年分类考试…」），取首个数字会得到 2026，
    //      页面就显示成「2026最低 2026 分」；用 \d{2,3} 去捞还会把「2026」切碎成「202」。
    //   ② 大量条目其实是「公网未公布 / 来源待核」的说明文字，里面根本没有分数。
    //      这时正确答案是 **null**（页面显示「—」），绝不能从文案里随便捡一个数字充当分数。
    // 因此：只在**明确带「最低/录取线/投档线」语义**时才取值，否则一律 null。
    c.minScore2026 = (function (txt) {
      if (!txt) return null;
      var s = String(txt);
      // 明确否定语义 → 该校 2026 没有公开录取分，直接 null
      if (/未公布|未公开|未检索到|无.*可查|待核|未在网页|具体分值未|无法获取|仅.*本人/.test(s) && !/最低\s*\d/.test(s)) {
        return null;
      }
      var m;
      // ① 「最低…394分」/「最低分394」/「最低录取分 394」
      m = s.match(/最低[^0-9]{0,12}(\d{2,3}(?:\.\d+)?)\s*分/);
      if (m) { var v = parseFloat(m[1]); if (v >= 100 && v <= 750) return v; }
      m = s.match(/最低分?\s*[:：]?\s*(\d{2,3}(?:\.\d+)?)/);
      if (m) { var v2 = parseFloat(m[1]); if (v2 >= 100 && v2 <= 750) return v2; }
      // ② 「录取线394分」「投档线 394」
      m = s.match(/(?:录取线|投档线|分数线)\s*[:：]?\s*(\d{2,3}(?:\.\d+)?)/);
      if (m) { var v3 = parseFloat(m[1]); if (v3 >= 100 && v3 <= 750) return v3; }
      // ③ 「普高最低394分；中职最低256分」这类已在 ① 覆盖；其余一律不猜
      return null;
    })(c.realScore2026);

    // 解析2026分类招生计划：普高、中职、专项

    var _planStr = c.plan2026 || '';

    var _gz = _planStr.match(/(?:普高|高中)\s*(\d+)/);

    var _zz = _planStr.match(/中职\s*(\d+)/);

    var _zxMatches = _planStr.match(/(?:退役军人|革命老区|乡村医生|专项|定向)[^+\d]*(\d+)/g);

    var _zx = 0;

    if (_zxMatches) {

      _zxMatches.forEach(function(m) {

        var n = m.match(/(\d+)/);

        if (n) _zx += parseInt(n[1]);

      });

    }

    c.plan2026Gaozhong = _gz ? parseInt(_gz[1]) : null;

    c.plan2026Zhongzhi = _zz ? parseInt(_zz[1]) : null;

    c.plan2026Zhuanxiang = _zx > 0 ? _zx : null;

    // 院校级：是否为估算（未采集到官方章程即为估算）

    c.plan2026Estimated = /未采集|首次参与/.test(_planStr);

    // 2026分专业计划：按2025年各专业占比分配2026总计划，并拆分普高/中职/专项

    var _total2026 = _planStr.match(/(\d+)\s*人/);

    // 如果没有2026总计划数字，用2025年各专业合计作为估算总计划

    var total2026 = _total2026 ? parseInt(_total2026[1]) : 0;

    if (!total2026 && c.majors && c.majors.length > 0) {

      c.majors.forEach(function(m) { total2026 += (m.plan2025 || m.plan2024 || 0); });

    }

    if (total2026 > 0 && c.majors && c.majors.length > 0 && !c.stoppedEnrollment) {

      // 院校级普高/中职/专项合计（用于分专业拆分）

      var gzSum = c.plan2026Gaozhong || 0;

      var zzSum = c.plan2026Zhongzhi || 0;

      var zxSum = c.plan2026Zhuanxiang || 0;

      var knownSplit = (gzSum + zzSum + zxSum) > 0;

      var ratioGz = knownSplit ? gzSum / total2026 : 1;

      var ratioZz = knownSplit ? zzSum / total2026 : 0;

      var ratioZx = knownSplit ? zxSum / total2026 : 0;

      var total2025 = 0;

      c.majors.forEach(function(m) { total2025 += (m.plan2025 || m.plan2024 || 0); });

      if (total2025 > 0) {

        // 先统计已有真实2026分专业计划的专业，跳过这些专业的估算

        var realPlanSum = 0;

        var realMajors = [];

        c.majors.forEach(function(m) {

          if (m.plan2026 && m.plan2026Estimated === false) {

            realPlanSum += m.plan2026;

            realMajors.push(m);

          }

        });

        var remainingTotal = total2026 - realPlanSum;

        var remaining2025 = total2025;

        realMajors.forEach(function(m) { remaining2025 -= (m.plan2025 || m.plan2024 || 0); });

        var allocated = 0;

        c.majors.forEach(function(m, idx) {
        if (m.noPlan2026) { m.plan2026 = 0; m.plan2026Gaozhong = 0; m.plan2026Zhongzhi = 0; m.plan2026_gaozhong = 0; m.plan2026_zhongzhi = 0; m.plan2026_zhuanxiang = 0; m.plan2026Estimated = false; return; }

          // 已有真实数据的专业，跳过估算

          if (m.plan2026 && m.plan2026Estimated === false) {

            // 确保分专业拆分字段存在

            if (!m.plan2026Gaozhong && m.plan2026_gaozhong == null) {

              m.plan2026_gaozhong = Math.round(m.plan2026 * ratioGz);

              m.plan2026_zhongzhi = Math.round(m.plan2026 * ratioZz);

              m.plan2026_zhuanxiang = m.plan2026 - m.plan2026_gaozhong - m.plan2026_zhongzhi;

              if (m.plan2026_zhuanxiang < 0) m.plan2026_zhuanxiang = 0;

            }

            return;

          }

          // 没有真实数据的专业，按剩余计划比例估算

          var ratio = remaining2025 > 0 ? (m.plan2025 || m.plan2024 || 0) / remaining2025 : 0;

          var isLastEstimated = idx === c.majors.length - 1 || c.majors.slice(idx + 1).every(function(x) { return x.plan2026 && x.plan2026Estimated === false; });

          if (isLastEstimated) {

            m.plan2026 = remainingTotal - allocated;

          } else {

            m.plan2026 = Math.round(remainingTotal * ratio);

            allocated += m.plan2026;

          }

          // 分专业拆分（按院校级普高/中职/专项比例）

          m.plan2026_gaozhong = Math.round(m.plan2026 * ratioGz);

          m.plan2026_zhongzhi = Math.round(m.plan2026 * ratioZz);

          m.plan2026_zhuanxiang = m.plan2026 - m.plan2026_gaozhong - m.plan2026_zhongzhi;

          if (m.plan2026_zhuanxiang < 0) m.plan2026_zhuanxiang = 0;

          // 院校总计划为真实数据时，分专业为按占比分配（标注）；院校本身未采集到章程时为估算

          m.plan2026Estimated = c.plan2026Estimated ? true : '按2025占比分配';

        });

      }

    }

    // 招生办电话
    // 注意：这里是**按公式拼出来的占位号码**（区号 + id 取模），不是真实电话。
    // 对已标记「待补」的院校不生成，避免页面把假号码当真实信息展示给学生。
    var area = AREA[c.city] || '0551';
    if (ph.phone) {

      c.phone = null;

    } else if (!c.phone) {

      c.phone = area + '-' + (1000 + ((c.id * 137) % 8000)) + '-' + (1000 + ((c.id * 53) % 8999));

    }

    // 在校生规模（估算，本科院校偏大）
    // 注意：只在没有真实值时才兜底，否则会覆盖掉从官网「学校简介」查到的真值。
    if (ph.scale) {

      c.scale = null;

    } else if (c.scale && !/^约\d+人$/.test(c.scale)) {

      // 已是官网原文表述（如「全日制在校生19000余人」「各类在校生近3万人」），保留不动

    } else if (!c.scale) {

      var sc = isBenke ? (15000 + (c.id % 6) * 2000) : (c.nature === '公办' ? (12000 + (c.id % 8) * 1000) : (8000 + (c.id % 6) * 1000));

      c.scale = '约' + sc + '人';

    }

  });

})();

